-- Explicit reviewed snapshot for litigation_diego_morales_47/maps; no runtime content generator.
CREATE TEMP TABLE _seed_place_categories (category_key TEXT PRIMARY KEY, category_value TEXT NOT NULL);
CREATE TEMP TABLE _seed_review_times (time_key TEXT PRIMARY KEY, status_review_time TEXT NOT NULL);
CREATE TEMP TABLE _seed_place_contacts (contact_key TEXT PRIMARY KEY, recipient_phone TEXT NOT NULL);
CREATE TEMP TABLE _seed_reviewers (reviewer_key TEXT PRIMARY KEY, reviewer_name TEXT NOT NULL);
DROP TABLE _seed_place_categories;
DROP TABLE _seed_place_contacts;
DROP TABLE _seed_reviewers;
DROP TABLE _seed_review_times;

