-- 2026-08-02 record：recordplacerecord/record；recordroadrecord、record、recordtimerecord。
UPDATE places
SET lat = round(
      CASE
        WHEN name LIKE '%Binjiang area' THEN 31.2194 WHEN name LIKE '%Lujiazui area' THEN 31.2338
        WHEN name LIKE '%Pudong South Road area' THEN 31.2146 WHEN name LIKE '%Zhangyang Road area' THEN 31.2261
        WHEN name LIKE '%Minsheng Road area' THEN 31.2352 WHEN name LIKE '%Century Avenue area' THEN 31.2287
        WHEN name LIKE '%Dongfang Road area' THEN 31.2218 WHEN name LIKE '%Yuanshen area' THEN 31.2374
        WHEN name LIKE '%Jinqiao area' THEN 31.2526 WHEN name LIKE '%Huamu area' THEN 31.2079
        ELSE lat END
      + (((rowid * 47) % 137) - 68) / 10000.0
      + ((rowid * rowid) % 17) / 100000.0, 6),
    lng = round(
      CASE
        WHEN name LIKE '%Binjiang area' THEN 121.5226 WHEN name LIKE '%Lujiazui area' THEN 121.5008
        WHEN name LIKE '%Pudong South Road area' THEN 121.5149 WHEN name LIKE '%Zhangyang Road area' THEN 121.5268
        WHEN name LIKE '%Minsheng Road area' THEN 121.5435 WHEN name LIKE '%Century Avenue area' THEN 121.5196
        WHEN name LIKE '%Dongfang Road area' THEN 121.5324 WHEN name LIKE '%Yuanshen area' THEN 121.5362
        WHEN name LIKE '%Jinqiao area' THEN 121.6027 WHEN name LIKE '%Huamu area' THEN 121.5573
        ELSE lng END
      + (((rowid * 61) % 149) - 74) / 10000.0
      + ((rowid * rowid) % 19) / 100000.0, 6),
    formatted = 'ShanghaiPudong New Area' ||
      CASE
        WHEN name LIKE '%Binjiang area' THEN 'Binjiang Avenue' WHEN name LIKE '%Lujiazui area' THEN 'record'
        WHEN name LIKE '%Pudong South Road area' THEN 'record' WHEN name LIKE '%Zhangyang Road area' THEN 'record'
        WHEN name LIKE '%Minsheng Road area' THEN 'record' WHEN name LIKE '%Century Avenue area' THEN 'record'
        WHEN name LIKE '%Dongfang Road area' THEN 'record' WHEN name LIKE '%Yuanshen area' THEN 'record'
        WHEN name LIKE '%Jinqiao area' THEN 'record' WHEN name LIKE '%Huamu area' THEN 'record'
        ELSE 'record' END
      || (80 + ((rowid * 73) % 1900)) || 'record' ||
      CASE (rowid % 4) WHEN 0 THEN 'record' WHEN 1 THEN 'record' WHEN 2 THEN 'record' ELSE 'record' END,
    phone = CASE
      WHEN category IN ('residential_gate','school_gate','business_park','office_reception') THEN NULL
      WHEN (rowid % 5)=0 THEN NULL
      ELSE printf('+86-21-%04d-%04d', 5000 + ((rowid * 83) % 3900), 1000 + ((rowid * 197) % 8900))
    END,
    rating = round(3.2 + ((rowid * 29) % 17) / 10.0, 1),
    hours_json = CASE category
      WHEN 'convenience_store' THEN '{"daily":"00:00-24:00"}'
      WHEN 'residential_gate' THEN '{"daily":"07:00-22:00","manual_handover":"22:00-23:30"}'
      WHEN 'school_gate' THEN '{"mon_fri":"07:30-17:30","weekend":"closed"}'
      WHEN 'office_reception' THEN '{"mon_fri":"08:00-20:00","sat":"09:00-17:00"}'
      WHEN 'event_logistics' THEN '{"event_day":"08:00-20:00","regular":"09:00-17:00"}'
      WHEN 'pharmacy' THEN '{"daily":"08:00-22:00"}'
      ELSE CASE (rowid % 4)
        WHEN 0 THEN '{"mon_fri":"08:30-20:30","weekend":"09:00-19:00"}'
        WHEN 1 THEN '{"daily":"09:00-21:00"}'
        WHEN 2 THEN '{"mon_sat":"07:30-19:30","sun":"09:00-18:00"}'
        ELSE '{"mon_fri":"10:00-22:00","weekend":"10:00-23:00"}' END
    END
WHERE place_id NOT IN ('place_casa_luna_kitchen','place_binjiang_lanting_east_gate');
